import { motion } from "framer-motion";
import styled, { ThemeProvider } from "styled-components";
import { lazy, Suspense } from "react";
import { lightTheme, mediaQueries } from "./Themes";

import { Design, Develope, Sisr } from "./AllSvgs";
import Loading from "../subComponents/Loading";

//Components
const SocialIcons = lazy(() => import("../subComponents/SocialIcons"));
const PowerButton = lazy(() => import("../subComponents/PowerButton"));
const LogoComponent = lazy(() => import("../subComponents/LogoComponent"));
const ParticlesComponent = lazy(() =>
  import("../subComponents/ParticlesComponent")
);
const BigTitle = lazy(() => import("../subComponents/BigTitle"));

const Box = styled(motion.div)`
  background-color: ${(props) => props.theme.body};
  width: 100vw;
  height: 100vh;
  position: relative;
  display: flex;
  gap: 10px;
  justify-content: space-evenly;
  align-items: center;

  ${mediaQueries(50)`
            flex-direction:column;  
            padding:8rem 0;
height:auto;
            &>*:nth-child(5){
              margin-bottom:5rem;
            }
           
  `};
  ${mediaQueries(30)`
           
            &>*:nth-child(5){
              margin-bottom:4rem;
            }
           
  `};
`;

const Main = styled(motion.div)`
  border: 2px solid ${(props) => props.theme.text};
  color: ${(props) => props.theme.text};
  background-color: ${(props) => props.theme.body};
  padding: 2rem;
  width: 25vw;
  height: 70vh;
  z-index: 3;
  line-height: 1.5;

  ${mediaQueries(60)`
            height: 55vh;
  `};

  ${mediaQueries(50)`
              width: 50vw;
              height: max-content;

  `};

  font-family: "Ubuntu Mono", monospace;

  display: flex;
  flex-direction: column;
  justify-content: space-between;

  &:hover {
    color: ${(props) => props.theme.body};
    background-color: ${(props) => props.theme.text};
  }
`;

const Title = styled.h2`
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: calc(1em + 1vw);

  ${mediaQueries(60)`
          font-size:calc(0.8em + 1vw);
  `};

  ${mediaQueries(50)`
          font-size:calc(1em + 2vw);
          margin-bottom:1rem;
  `};

  ${mediaQueries(30)`
                      font-size:calc(1em + 1vw);
  `};
  ${mediaQueries(25)`
                      font-size:calc(0.8em + 1vw);
                      svg{
                        width:30px;
                        height:30px;
                      }
  `};

  ${Main}:hover & {
    & > * {
      fill: ${(props) => props.theme.body};
    }
  }

  & > *:first-child {
    margin-right: 1rem;
  }
`;
const Description = styled.div`
  color: ${(props) => props.theme.text};
  font-size: calc(0.6em + 1vw);
  padding: 0.5rem 0;
  ${Main}:hover & {
    color: ${(props) => props.theme.body};
  }

  ${mediaQueries(50)`
            font-size: calc(0.8em + 1vw);

  `};

  ${mediaQueries(30)`
                      font-size:calc(0.7em + 1vw);

              

  `};

  ${mediaQueries(25)`
                      font-size:calc(0.5em + 1vw);

              

  `};

  strong {
    margin-bottom: 1rem;
    text-transform: uppercase;
  }
  ul,
  p {
    margin-left: 2rem;
  }
`;

const Bts = () => {
  return (
    <ThemeProvider theme={lightTheme}>
      <Suspense fallback={<Loading />}>
        <Box
          key="Bts"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1, transition: { duration: 1 } }}
          exit={{ opacity: 0, transition: { duration: 0.5 } }}
        >
          <LogoComponent theme="light" />
          <PowerButton />
          <SocialIcons theme="light" />
          <ParticlesComponent theme="light" />

          <Main>
            <Title>
              <Design width={40} height={40} /> BTS SIO
            </Title>
            <Description>
            Services Informatiques aux Organisations.
            </Description>
            <Description>
              <strong>Qu’est-ce que le BTS SIO ?</strong> <br />
              <ul>
                <li>Le BTS SIO est un diplôme reconnu par l’état de niveau Bac+2, qui après le 1er semestre se distingue en 2 options Slam et Sisr.</li>
              </ul>
            </Description>
            <Description>
              <strong>Poursuites d'études.</strong> <br />
              <ul>
                <li>Ecole d'ingénieur.</li>
                <li>Licence Professionnelle.</li>
                <li>Master développement web.</li>
                <li>Bachelor chef de projets informatiques.</li>
              </ul>
            </Description>
          </Main>
          <Main>
            <Title>
              <Develope width={40} height={40} /> Option SLAM
            </Title>
            <Description>
            Solutions Logicielles et application Métier.
            </Description>
            <Description>
              <strong>SPÉCIALITÉ SLAM</strong> <br />
              <ul>
                <li>Exploitation d’un schéma de données</li>
                <li>Programmation objet</li>
                <li>Conception et adaptation d’une base de données (BDD)</li>
                <li>Réalisation et maintenance de composants logiciels</li>
              </ul>
            </Description>
            <Description>
              <strong>Métiers possibles</strong> <br />
              <ul>
                <li>Développeur informatique.</li>
                <li>Analyste programmeur.</li>
                <li>Chef de projet informatique.</li>

              </ul>
            </Description>
          </Main>

          <Main>
            <Title>
              <Sisr width={40} height={40} /> Option SLAM
            </Title>
            <Description>
            Solutions d'infrastructures systèmes et réseaux.
            </Description>
            <Description>
              <strong>SPÉCIALITÉ SISR</strong> <br />
              <ul>
                <li>Maintenance des accès utilisateurs.</li>
                <li>Conception des infrastructures réseaux.</li>
                <li>Administration des systèmes informatiques.</li>
                <li>Supervision des réseaux.</li>
              </ul>
            </Description>
            <Description>
              <strong>Métiers possibles</strong> <br />
              <ul>
                <li>Administrateur systèmes et réseaux.</li>
                <li>Technicien d'infrastructure.</li>
              </ul>
            </Description>
          </Main>

          <BigTitle text="Bts" top="80%" right="30%" />
        </Box>
      </Suspense>
    </ThemeProvider>
  );
};

export default Bts;
